const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const palmSprings = ee.Geometry.Point([-116.5453, 33.8303]);
  const scale = 1000; // MODIS LST resolution

  // 2. Data Acquisition & Processing Function
  const modisLST = ee.ImageCollection('MODIS/061/MOD11A1');

  const processLST = function(image) {
    // Select the daytime LST band and the Quality Control band
    const lstDay = image.select('LST_Day_1km');
    const qcDay = image.select('QC_Day');
    // Mask pixels with low quality (bits 0-1 != 0, i.e., not "good data")
    const qualityMask = qcDay.bitwiseAnd(0b11).eq(0);
    // Apply scale factor to get Kelvin, then convert to Celsius, and apply mask
    const lstCelsius = lstDay.multiply(0.02).subtract(273.15).updateMask(qualityMask);
    return lstCelsius.rename('LST');
  };

  // 3. Target Period (2017)
  const targetCollection = modisLST
    .filterDate('2017-07-15', '2017-07-22')
    .filterBounds(palmSprings)
    .map(processLST);

  // Check if target data exists
  const targetSize = targetCollection.size().getInfo();
  if (targetSize === 0) {
    console.log("No images found for the target period (2017).");
    console.log("A"); // The final answer tag is on the last line
    return;
  }
  const targetMeanImage = targetCollection.mean();

  // 4. Baseline Period (2001-2010)
  const baselineCollection = modisLST
    .filter(ee.Filter.calendarRange(2001, 2010, 'year'))
    .filter(ee.Filter.calendarRange(196, 202, 'day_of_year')) // July 15-21
    .filterBounds(palmSprings)
    .map(processLST);

  // Check if baseline data exists
  const baselineSize = baselineCollection.size().getInfo();
  if (baselineSize === 0) {
    console.log("No images found for the baseline period (2001-2010).");
    console.log("C1");
    return;
  }
  const baselineMeanImage = baselineCollection.mean();

  // 5. Pixel Count and Value Extraction
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const targetResult = targetMeanImage.reduceRegion({
    reducer: reducer,
    geometry: palmSprings,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const baselineResult = baselineMeanImage.reduceRegion({
    reducer: reducer,
    geometry: palmSprings,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const targetPixels = targetResult.LST_count;
  const baselinePixels = baselineResult.LST_count;

  if (targetPixels === 0) {
    console.log("Target period 2017 has no valid pixels after masking.");
    console.log("C2");
    return;
  }
  if (baselinePixels === 0) {
    console.log("Baseline period 2001-2010 has no valid pixels after masking.");
    console.log("C2");
    return;
  }

  const targetTemp = targetResult.LST_mean;
  const baselineTemp = baselineResult.LST_mean;

  // Check for calculation failures
  if (targetTemp === null || baselineTemp === null) {
      console.log(`Calculation failed: Target Temp=${targetTemp}, Baseline Temp=${baselineTemp}`);
      console.log("C3");
      return;
  }

  // 6. Validation & Final Answer
  console.log(`Target Period (2017): ${targetTemp.toFixed(2)} C from ${targetPixels} valid pixel(s).`);
  console.log(`Baseline Period (2001-2010): ${baselineTemp.toFixed(2)} C from ${baselinePixels} valid pixel(s).`);

  if (targetTemp > baselineTemp) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error during Earth Engine initialization or analysis: ${e}`);
    console.log("D");
  }
}

initEE();
